// UbigeoProvincia returns the entry for code and whether it is a known Provincia (INEI) code.
func UbigeoProvincia(code string) (UbigeoProvinciaEntry, bool) {
	e, ok := ubigeoProvincia[code]
	return e, ok
}

// UbigeoProvinciaValid reports whether code is a known Provincia (INEI) code.
func UbigeoProvinciaValid(code string) bool {
	_, ok := ubigeoProvincia[code]
	return ok
}

// UbigeoProvinciaDepartamento returns the departamento of code, or "" if the code is unknown.
func UbigeoProvinciaDepartamento(code string) string {
	return ubigeoProvincia[code].Departamento
}
